const clock = new THREE.Clock();
scene.background = new THREE.Color(0xf4f7fb);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;

const ambientLight = new THREE.AmbientLight(0x7f8aa6, 0.32);
const keyLight = new THREE.DirectionalLight(0xffffff, 1.35);
keyLight.position.set(6, 10, 8);
keyLight.castShadow = true;
const fillLight = new THREE.DirectionalLight(0xbfd7ff, 0.55);
fillLight.position.set(-7, 4, 5);
const pointLight = new THREE.PointLight(0xffaa00, 1.2, 20);
pointLight.position.set(3, 4, 3);
pointLight.castShadow = true;

scene.add(ambientLight, keyLight, fillLight, pointLight);

const geometry = new THREE.BoxGeometry(1.6, 1.6, 1.6);
const material = new THREE.MeshStandardMaterial({ color: 0xe63946, roughness: 0.4, metalness: 0.1 });
const cube = new THREE.Mesh(geometry, material);
cube.castShadow = true;
cube.receiveShadow = true;
scene.add(cube);

camera.position.set(3.5, 2.5, 4.5);
camera.lookAt(0, 0, 0);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  cube.rotation.x = t * 0.4;
  cube.rotation.y = t * 0.6;
  controls.update();
  renderer.render(scene, camera);
}
animate();

